def test_lowercases_and_hyphenates_spaces():
    assert slugify("New high priority thing") == "new-high-priority-thing"


def test_collapses_runs_of_non_alphanumeric():
    assert slugify("fix db!") == "fix-db"
    assert slugify("   ---   ") == ""


