    assert slugify("Fix DB") == slugify("fix db!") == "fix-db"


def test_symbols_only_title_yields_empty_slug():
    # P9 audit finding (docs/features/draft/tickets-create.md): NOT NULL doesn't reject "".
    assert slugify("!!!") == ""


